import{_ as t,H as a,f as p,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"23 | 团队开发的核心模式","description":"","frontmatter":{},"headers":[{"level":2,"title":"技术方案的应用","slug":"技术方案的应用","link":"#技术方案的应用","children":[]},{"level":2,"title":"软件质量的保证","slug":"软件质量的保证","link":"#软件质量的保证","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"徐昊·AI时代的软件工程/23｜团队开发的核心模式.md","filePath":"徐昊·AI时代的软件工程/23｜团队开发的核心模式.md","lastUpdated":1795556403000}'),n={name:"徐昊·AI时代的软件工程/23｜团队开发的核心模式.md"};function l(r,e,s,o,h,B){return a(),p("div",null,[...e[0]||(e[0]=[i('<h1 id="_23-团队开发的核心模式" tabindex="-1">23 | 团队开发的核心模式 <a class="header-anchor" href="#_23-团队开发的核心模式" aria-label="Permalink to &quot;23 | 团队开发的核心模式&quot;">​</a></h1><p>你好，我是徐昊，今天我们来继续学习 AI 时代的软件工程。</p><p>在这章前面的 8 节课中，我们讲解了使用大语言模型（Large Language Model，LLM）辅助软件开发的核心思路，也就是使用测试驱动的方法与 LLM 进行结对编程。然后我们依次引入了测试策略以及测试工序，帮助我们逐渐提高 LLM 生成代码的质量，让 LLM 写出符合我们架构要求的代码。</p><p>今天，让我们站在团队的角度上，来总结一下，在软件开发过程中的两个核心知识过程，即技术方案的应用以及软件质量的保证。</p><h2 id="技术方案的应用" tabindex="-1">技术方案的应用 <a class="header-anchor" href="#技术方案的应用" aria-label="Permalink to &quot;技术方案的应用&quot;">​</a></h2><p>宏观上讲，编码的过程是技术方案应用的过程。除了要实现特定的功能之外，对于如何实现这些功能也有具体的要求，也就是要符合技术方案中提出的约束与条件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/23/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/23/1.png" alt=""></a></p><p>我们在业务知识管理的过程中，主要关注点在理解业务的需求，明确要解决的问题等等。而在具体的开发过程中，关注的重点，就变成了如何保证实现代码与技术方案要求是一致的。</p><p>通常而言，对于技术方案的应用处于庞杂的认知行为模式（Complicated）。理解业务需求就是感知（Sense），按照技术方案分解任务就是分析（Analysis），依照任务列表完成代码就是响应（Respond）。</p><p>对于技术方案的应用处于庞杂模式，给了我们两个极为重要的洞见。第一，作为不可言说知识的技术方案，需要预先被提取出来。也就是说，进入到开发环节时，我们主要是不可言说知识的应用，而不是不可言说知识的学习；第二，由于应用技术方案处于庞杂认知模式，那么效率的关键是团队的放大效应，而不是个人的有效性和效率。</p><p>对于技术方案的提前提取和准备是非常重要的。这意味着在项目开始之前，团队需要花费时间来研究和理解可能适用的技术方案，以及它们如何适应特定的业务需求。比如，是采用微服务架构还是单体架构。如果是微服务架构，服务的边界大致是什么样子的等等；再比如，系统是如何部署的，弹性边界是如何划分的，是可用性优先还是一致性优先等等。</p><p>但是更重要的是，我们要将这种不可言说知识形成团队共识（团队放大）。否则，团队中就会出现认知分歧。所谓认知分歧，是指一部分人处在庞杂认知行为模式，另一部分人处于复杂的认知模式。那么处于低认知行为的团队成员，就会引入质量缺陷，带来效率的损失。</p><p>比如，如果团队中有的成员不能理解团队要求的技术方案，那么他们就极有可能写出功能正确但是不符合技术方案的代码。这样的代码实际是存在质量缺陷的代码。质量缺陷可能体现在跨功能特性的缺失，丧失可扩展性，引入不恰当的耦合等等。早晚都会导致返工与重做。</p><p>因而，对于技术方案的应用，从团队水平来看，应该达到庞杂的认知行为模式，才能保证技术方案的顺利落地。这是从知识工程角度看待技术方案落地时，自然而然产生的结论。</p><p>当然，这与我们平时工作的实际情况会存在很大的出入。大把的架构师将精力放在技术方案的提前提取和准备上，而忽略了在团队中认知行为基线的建立。于是，我经常给他们讲一个神雕侠侣里的故事。</p><p>神雕侠侣里公孙止有一套奇怪的武功可以闭穴，但是条件极为苛刻，需要戒忌荤腥。于是在与杨过比武的时候，裘千尺就咬破了手指滴血到两碗茶里，给他和杨过喝，这样他的功夫就破了。裘千尺就跟公孙止说，我早说过你这功夫难练易破，所以不练也罢。</p><p>类似地，架构师的工作很多时候跟公孙止一样，虽然他们费尽了心思，为满足各种约束设计了巧妙的技术方案。但是开发却无法有效地应用这些知识，无法写出满足技术方案的代码，再巧妙的方案也就破了（落不了地）。所以我也对他们说，你们的方案 / 架构 / 框架，难练易破，不练也罢。</p><p>正如 Peter Drucker 所说，知识工作者的效率是知识消费的效率，而非知识生产的效率。知识工程也要从消费的角度去衡量工程的效率。如果无法构建高效的消费渠道，那么 title 光鲜的架构师，也不过是一个个破了功的公孙止罢了。</p><h2 id="软件质量的保证" tabindex="-1">软件质量的保证 <a class="header-anchor" href="#软件质量的保证" aria-label="Permalink to &quot;软件质量的保证&quot;">​</a></h2><p>除了应用技术方案之外，我们还需要关注软件的质量。软件的质量有一点较为特殊，那就是它是适用性质量，而非符合性质量。</p><p>符合性质量概念以符合现行标准的程度作为衡量依据，“符合标准”就是合格的产品质量，符合的程度反映了产品质量的水平。</p><p>比如说我做一个杯子，没什么特别的要求，也不是我神经质的艺术作品，就是普普通通的一个杯子。那么就需要高矮长短，大小胖瘦等等一干质量属性，我做好了可以拿着质量标准来对比，一眼就可以看出哪里出了什么问题。也就是通过是否符合这些标准，判断产品是否达到相应的质量。</p><p>而适用性质量概念以适合顾客需要的程度作为衡量的依据，从使用的角度定义产品质量，认为质量就是产品的“适用性”，是“产品在使用时能够成功满足用户需要的程度”。质量涉及设计开发、制造、销售、服务等过程，形成了广义的质量概念。比如，一件工艺优秀但是不合身的衣服，就是适用性质量不足而符合性质量满分的产品。</p><p>软件的基本质量就是要在用户使用的过程中发挥价值，支撑客户的业务发展。也因为软件“软”的特性，客户对于软件质量的期待，是有持续性的，是可以“持续满足业务发展诉求”的。那么，“可根据业务的改变持续演化”就是软件的基础质量要求之一。</p><p>因此，软件的质量并不是由后验式的质量检查决定的，而是由软件开发的过程决定的。在软件开发的过程中，需要为软件的持续演化提供基础的支撑，这也决定了软件的质量。</p><p>这就是 Edwards Deming 的质量管理理论。他认为，优秀的结果不是偶然发生的，而是通过管理和改进过程来实现的。也就是著名的内建质量（Build Quality In）。</p><p>显而易见，测试策略（Testing Strategy）是我们实现质量内建的重要手段。特别是“用以支撑团队的测试”，是软件可持续演化的重中之重。</p><p>与技术方案类似，通常对测试策略的应用也是庞杂的认知行为模式（Complicated）。因而，它也是不可言说知识的应用，而不是不可言说知识的学习；效率的关键是团队的放大效应，而不是个人的有效性和效率。它同样会产生团队的认知分歧，以及由此带来的质量缺陷和效率损失。同样的，QA（而非 Tester）也容易成为一群公孙止。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>从知识过程看待团队软件开发时，知识的传递很容易就成为团队效率的瓶颈，再优秀的实践，都会因为认知分歧的存在，让我们陷入“公孙止困境”。而大语言模型恰恰可以在知识传递上，给我们带来极大的改进。核心模式就是利用思维链（Chain of Thought，CoT）作为可复用的认知提升工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/23/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BE%90%E6%98%8A%C2%B7AI%E6%97%B6%E4%BB%A3%E7%9A%84%E8%BD%AF%E4%BB%B6%E5%B7%A5%E7%A8%8B/images/23/2.png" alt=""></a></p><p>如上图所示，具备高认知能力的人，以思维链 + 任务模板的形式将不可言说知识构造为可以传递的形态。认知能力较低的，则通过使用思维链，获得生成的任务列表，检查任务列表，并按照任务列表的指引，使用对应的任务模板，完成任务。</p><p>这里需要注意的是，对于认知能力较低的人来说，当他们第一开始使用思维链 + 任务模版时，并不能直接处于庞杂认知模式。他们更多仍然是处于复杂的认知行为模式，也就是对于不可言说知识的学习状态。但是这时学习的内容发生了改变。他们学习的主要内容是思维链中包含的思路和工作方法。</p><p>也就是说，他们学习的不是如何实现某个功能，而是技术方案是如何被应用的。这时候，通过CoT 拆分任务，以及围绕任务列表进行反馈，就构成了一个反馈的循环。加速了他们对于不可言说知识的掌握。</p><p>而当他们逐渐掌握 CoT 中的思路时，他们才能对于任务列表的质量给出准确的判断，他们也就进入了庞杂的认知行为模式。团队中的认知分歧也就消除了。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>想一想，测试工序是如何将架构和测试策略结合在一起的。</p><p>欢迎在留言区分享你的想法，我会让编辑置顶一些优质回答供大家学习讨论。</p>',38)])])}const d=t(n,[["render",l]]);export{c as __pageData,d as default};
